		public static void SetupEvolveSituation(global::Pml.PokePara.EvolveSituation pSituation, bool isDeviceTurnedOver, global::SYS_WEATHER weather = (global::SYS_WEATHER)(20)) {
			if (weather == SYS_WEATHER.MAX)
				weather = PlayerWork.FieldWeather;

			// isEvening (+0x17), isTurnRoundOnField and criticalHitCount are not reset (@02bad6a8..b4 store +0x10..+0x16, +0x18, +0x19 only).
			pSituation.isMagneticField = false;
			pSituation.isIceField = false;
			pSituation.isMossField = false;
			pSituation.isSnowMountain = false;
			pSituation.isUltraSpace = false;
			pSituation.isMorningOrNoon = false;
			pSituation.isNight = false;
			pSituation.isDeviceTurnedOver = isDeviceTurnedOver;
			pSituation.isRain = false;

			DPData.MYSTATUS status = PlayerWork.playerStatus;
			pSituation.owner_info.trainerId = status.id;
			pSituation.owner_info.name = status.name;
			pSituation.owner_info.sex = status.sex ? (byte)0 : (byte)1;
			pSituation.owner_info.langID = status.region_code;

			SetupPlace(pSituation);

			switch (GameManager.currentPeriodOfDay)
			{
				case PeriodOfDay.Morning:
				case PeriodOfDay.Daytime:
					pSituation.isMorningOrNoon = true;
					break;
				case PeriodOfDay.Evening:
					pSituation.isMorningOrNoon = true;
					pSituation.isEvening = true;
					break;
				case PeriodOfDay.Night:
				case PeriodOfDay.Midnight:
					pSituation.isNight = true;
					break;
			}

			switch (weather)
			{
				case SYS_WEATHER.RAIN:
				case SYS_WEATHER.STRAIN:
				case SYS_WEATHER.SPARK:
					pSituation.isRain = true;
					break;
			}
		}
		private static void SetupPlace(global::Pml.PokePara.EvolveSituation pSituation) {
			switch (ZoneWork.GetShinkaPlaceID(PlayerWork.zoneID))
			{
				case Pml.Personal.EvolveCond.PLACE_MAGNETIC:
					pSituation.isMagneticField = true;
					break;
				case Pml.Personal.EvolveCond.PLACE_KOKE:
					pSituation.isMossField = true;
					break;
				case Pml.Personal.EvolveCond.PLACE_ICE:
					pSituation.isIceField = true;
					break;
				case Pml.Personal.EvolveCond.PLACE_SNOW_MOUNTAIN:
					pSituation.isSnowMountain = true;
					break;
				case Pml.Personal.EvolveCond.PLACE_ULTRA_SPACE:
				case Pml.Personal.EvolveCond.PLACE_ULTRA_SPACE_ITEM:
